/* ==========================================================================
   DUNGEON HAUL — Asset Showcase Gallery CSS
   Theme: Retro Pixel Vault / Glassmorphism Gold
   ========================================================================== */

@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@600;800;900&family=Inter:wght@400;500;600;700;800&family=Press+Start+2P&display=swap');

:root {
  --bg-dark: #090712;
  --bg-surface: #141026;
  --bg-card: rgba(26, 21, 48, 0.85);
  --bg-card-hover: rgba(38, 31, 70, 0.95);
  --border-gold: #d4a017;
  --border-muted: rgba(212, 160, 23, 0.25);

  --gold-primary: #f3c032;
  --gold-light: #ffe28a;
  --gold-dark: #b8860b;
  --gold-glow: rgba(243, 192, 50, 0.35);

  --badge-p0: #40e0a0;
  --badge-p1: #50a0e8;
  --badge-p2: #e070b0;

  --text-main: #f4efe4;
  --text-muted: #a8a3c1;
  --text-dim: #6e698b;

  --font-pixel: 'Press Start 2P', monospace;
  --font-heading: 'Cinzel', serif;
  --font-body: 'Inter', sans-serif;

  --max-width: 1320px;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 18px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-dark);
  background-image: 
    radial-gradient(circle at 50% 0%, rgba(243, 192, 50, 0.12) 0%, transparent 60%),
    radial-gradient(circle at 100% 100%, rgba(80, 160, 232, 0.08) 0%, transparent 50%);
  color: var(--text-main);
  font-family: var(--font-body);
  line-height: 1.6;
  min-height: 100vh;
}

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* Header Section */
header {
  padding: 48px 0 32px;
  text-align: center;
  border-bottom: 1px solid var(--border-muted);
}

.brand-badge {
  display: inline-block;
  font-family: var(--font-pixel);
  font-size: 11px;
  color: var(--gold-primary);
  background: rgba(243, 192, 50, 0.1);
  border: 1px solid var(--border-gold);
  padding: 6px 14px;
  border-radius: 20px;
  letter-spacing: 1px;
  margin-bottom: 16px;
  text-transform: uppercase;
}

h1 {
  font-family: var(--font-heading);
  font-size: 42px;
  font-weight: 900;
  color: var(--gold-light);
  text-shadow: 0 0 20px var(--gold-glow);
  letter-spacing: 2px;
  margin-bottom: 12px;
}

p.subtitle {
  color: var(--text-muted);
  font-size: 16px;
  max-width: 720px;
  margin: 0 auto 24px;
}

/* Controls Bar */
.controls-section {
  padding: 28px 0;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
  justify-content: space-between;
}

.search-box {
  position: relative;
  flex: 1;
  min-width: 280px;
  max-width: 420px;
}

.search-box input {
  width: 100%;
  padding: 12px 18px 12px 42px;
  background: var(--bg-surface);
  border: 1px solid var(--border-muted);
  border-radius: var(--radius-md);
  color: var(--text-main);
  font-family: var(--font-body);
  font-size: 14px;
  outline: none;
  transition: all 0.2s ease;
}

.search-box input:focus {
  border-color: var(--gold-primary);
  box-shadow: 0 0 12px var(--gold-glow);
}

.search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-dim);
}

.filter-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.filter-btn {
  background: var(--bg-surface);
  border: 1px solid var(--border-muted);
  color: var(--text-muted);
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.filter-btn:hover, .filter-btn.active {
  background: var(--gold-primary);
  color: var(--bg-dark);
  border-color: var(--gold-primary);
  box-shadow: 0 0 10px var(--gold-glow);
}

/* Asset Stats Summary */
.stats-bar {
  display: flex;
  gap: 20px;
  margin-bottom: 24px;
  background: var(--bg-surface);
  border: 1px solid var(--border-muted);
  padding: 14px 24px;
  border-radius: var(--radius-md);
}

.stat-item {
  font-size: 14px;
  color: var(--text-muted);
}

.stat-item strong {
  color: var(--gold-primary);
}

/* Asset Grid */
.asset-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 24px;
  padding-bottom: 60px;
}

.asset-card {
  background: var(--bg-card);
  border: 1px solid var(--border-muted);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  display: flex;
  flex-direction: column;
}

.asset-card:hover {
  transform: translateY(-4px);
  border-color: var(--border-gold);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5), 0 0 16px var(--gold-glow);
  background: var(--bg-card-hover);
}

.card-preview {
  position: relative;
  width: 100%;
  height: 200px;
  background: rgba(10, 8, 18, 0.9);
  display: flex;
  align-items: center;
  justify-content: center;
  border-bottom: 1px solid var(--border-muted);
  overflow: hidden;
}

.card-preview img {
  max-width: 90%;
  max-height: 90%;
  object-fit: contain;
  image-rendering: pixelated;
  transition: transform 0.3s ease;
}

.asset-card:hover .card-preview img {
  transform: scale(1.04);
}

.tier-badge {
  position: absolute;
  top: 12px;
  right: 12px;
  padding: 4px 10px;
  border-radius: 12px;
  font-family: var(--font-pixel);
  font-size: 9px;
  font-weight: bold;
  text-transform: uppercase;
}

.tier-p0 { background: rgba(64, 224, 160, 0.2); color: var(--badge-p0); border: 1px solid var(--badge-p0); }
.tier-p1 { background: rgba(80, 160, 232, 0.2); color: var(--badge-p1); border: 1px solid var(--badge-p1); }
.tier-p2 { background: rgba(224, 112, 176, 0.2); color: var(--badge-p2); border: 1px solid var(--badge-p2); }

.card-body {
  padding: 18px;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.asset-name {
  font-family: var(--font-heading);
  font-size: 18px;
  font-weight: 800;
  color: var(--gold-light);
  margin-bottom: 4px;
}

.asset-doc-id {
  font-family: monospace;
  font-size: 12px;
  color: var(--gold-primary);
  background: rgba(243, 192, 50, 0.08);
  padding: 2px 8px;
  border-radius: 4px;
  display: inline-block;
  margin-bottom: 12px;
  width: fit-content;
}

.meta-table {
  width: 100%;
  font-size: 13px;
  color: var(--text-muted);
  border-collapse: collapse;
  margin-top: 8px;
}

.meta-table td {
  padding: 4px 0;
}

.meta-table td.label {
  color: var(--text-dim);
  width: 90px;
}

.card-footer {
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--border-muted);
  font-size: 11px;
  color: var(--text-dim);
  word-break: break-all;
}

/* Footer */
footer {
  padding: 32px 0;
  text-align: center;
  border-top: 1px solid var(--border-muted);
  color: var(--text-dim);
  font-size: 13px;
}

