let currentFilter = 'all';
let searchQuery = '';

function renderGallery() {
  const grid = document.getElementById('assetGrid');
  grid.innerHTML = '';

  const filtered = ASSETS_DATA.filter(item => {
    // Filter check
    let matchesFilter = true;
    if (currentFilter === 'p0') matchesFilter = item.tier === 'P0';
    else if (currentFilter === 'p1') matchesFilter = item.tier === 'P1';
    else if (currentFilter === 'p2') matchesFilter = item.tier === 'P2';
    else if (currentFilter !== 'all') matchesFilter = item.category === currentFilter;

    // Search check
    let matchesSearch = true;
    if (searchQuery.trim() !== '') {
      const q = searchQuery.toLowerCase();
      matchesSearch = item.name.toLowerCase().includes(q) || item.docId.toLowerCase().includes(q) || item.category.toLowerCase().includes(q);
    }

    return matchesFilter && matchesSearch;
  });

  document.getElementById('visibleCount').innerText = filtered.length;
  document.getElementById('totalCount').innerText = ASSETS_DATA.length;

  if (filtered.length === 0) {
    grid.innerHTML = `<div style="grid-column: 1/-1; text-align: center; padding: 48px; color: var(--text-dim);">No assets found matching your criteria.</div>`;
    return;
  }

  filtered.forEach(asset => {
    const card = document.createElement('div');
    card.className = 'asset-card';
    card.innerHTML = `
      <div class="card-preview">
        <img src="${asset.thumb}" alt="${asset.name}" loading="lazy" onerror="this.src='../docs/art/preview/title_screen_art_1784605975053.jpg'">
        <span class="tier-badge tier-${asset.tier.toLowerCase()}">${asset.tier}</span>
      </div>
      <div class="card-body">
        <div>
          <div class="asset-name">${asset.name}</div>
          <div class="asset-doc-id">${asset.docId}</div>
          <table class="meta-table">
            <tr><td class="label">Category:</td><td>${asset.category}</td></tr>
            <tr><td class="label">Format:</td><td>${asset.format}</td></tr>
          </table>
        </div>
        <div class="card-footer">
          <strong>Path:</strong> <code>${asset.path}</code>
        </div>
      </div>
    `;
    grid.appendChild(card);
  });
}

document.addEventListener('DOMContentLoaded', () => {
  renderGallery();

  // Filter button listeners
  document.querySelectorAll('.filter-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      document.querySelectorAll('.filter-btn').forEach(b => b.classList.remove('active'));
      e.target.classList.add('active');
      currentFilter = e.target.getAttribute('data-filter');
      renderGallery();
    });
  });

  // Search input listener
  const searchInput = document.getElementById('searchInput');
  if (searchInput) {
    searchInput.addEventListener('input', (e) => {
      searchQuery = e.target.value;
      renderGallery();
    });
  }
});

