function renderCanvasFrame(canvas, atlasImageUrl, coords, scale = 1) {
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;

  // Target display size for card thumbnail container
  const maxW = 220;
  const maxH = 160;

  let drawW = coords.w;
  let drawH = coords.h;

  // Auto-fit larger atlas frames inside thumbnails while preserving pixel crispness
  if (drawW > maxW || drawH > maxH) {
    const scaleFit = Math.min(maxW / drawW, maxH / drawH);
    drawW = Math.round(drawW * scaleFit);
    drawH = Math.round(drawH * scaleFit);
  } else if (drawW < 64 && drawH < 64) {
    drawW = drawW * 2;
    drawH = drawH * 2;
  }

  canvas.width = drawW;
  canvas.height = drawH;

  const img = new Image();
  img.onload = () => {
    ctx.clearRect(0, 0, drawW, drawH);
    ctx.drawImage(
      img,
      coords.x, coords.y, coords.w, coords.h,
      0, 0, drawW, drawH
    );
  };
  img.src = atlasImageUrl;
}

