            if (r > 210 and g > 210 and b > 210) or (r < 55 and g < 55 and b < 65):
                bg_mask[y, x] = True

    visited = np.zeros((h, w), dtype=bool)
    queue = deque()

    for x in range(w):
        if bg_mask[0, x]: queue.append((0, x)); visited[0, x] = True
        if bg_mask[h-1, x]: queue.append((h-1, x)); visited[h-1, x] = True
    for y in range(h):
        if bg_mask[y, 0]: queue.append((y, 0)); visited[y, 0] = True
        if bg_mask[y, w-1]: queue.append((y, w-1)); visited[y, w-1] = True

    while queue:
        cy, cx = queue.popleft()
        for dy, dx in [(-1,0), (1,0), (0,-1), (0,1)]:
            ny, nx = cy + dy, cx + dx
            if 0 <= ny < h and 0 <= nx < w and not visited[ny, nx]:
                if bg_mask[ny, nx]:
                    visited[ny, nx] = True
                    queue.append((ny, nx))

    for y in range(h):
        for x in range(w):
            if visited[y, x]:
                arr[y, x] = [0, 0, 0, 0]

    return Image.fromarray(arr)

