function renderModalCanvasFrame(canvas, atlasImageUrl, coords) {
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;

  // Render cleanly at 3x scale for detail inspection
  const scale = 3;
  const drawW = coords.w * scale;
  const drawH = coords.h * scale;

  canvas.width = drawW;
  canvas.height = drawH;

  const img = new Image();
  img.onload = () => {
    ctx.clearRect(0, 0, drawW, drawH);
    ctx.drawImage(
      img,
      coords.x, coords.y, coords.w, coords.h,
      0, 0, drawW, drawH
    );
  };
  img.src = atlasImageUrl;
}

